PageView = class("PageView", View)

function PageView:ctor()
    PageView.super.ctor(self);
    self.uiPage = nil;
end

-- 各个子View从Page获取所需的部件，存入self。
function PageView:Load(callback)
    --Debug.LogWarning("2.####->PageView:Load->"..tostring(self));
    --if LuaRefreshScript.pageArr[self.__cname] then --加载过的不加载,重启lua用
    --    return
    --end
    local uiPage = nil;
    uiSystem:CreatePageX(self.name, function(page, exist)
        --Debug.LogWarning("PageView:Load===>>>>"..tostring(exist));
        if exist == false then
            uiPage = page;
            if uiPage == nil then
                GameDebugger.sPushLog("Create page failed!-"..self.name);
            else
                self.uiPage = uiSystem:GetPage(self.name);
                self.gameObject = self.uiPage.gameObject;
                self.transform = self.gameObject.transform;
                --LuaRefreshScript.pageArr[self.__cname] = self.uiPage --存储加载好的对象,重启lua用
                GameDebugger.sPushLog("[Lua]View完成加载:"..self.name.."-"..tostring(self.uiPage));
            end
            --下面这个重载方法不能随便更换顺序，放在下面，确保OnViewLoaded正确。
            PageView.super.Load(self, callback);
        end
    end);
end

